function mint(address,uint256)(address owner, uint256 amount) {
  map[1][owner] = (map_get(1, owner) Add amount) @ Some("true")
}

function approve(address,address,uint256)(address owner, address spender, uint256 amount) {
  let key = keccak256(owner, spender)
  map[2][key] = amount @ Some("true")
}

function transfer(address,address,uint256)(address from, address to, uint256 amount) {
  let fromBalance = map_get(1, from)
  abort_if Not((fromBalance Gte amount))
  map[1][from] = (fromBalance Sub amount) @ Some("true")
  map[1][to] = (map_get(1, to) Add amount) @ Some("true")
  return 1
}

function transferFrom(address,address,address,uint256)(address owner, address spender, address to, uint256 amount) {
  let key = keccak256(owner, spender)
  let allowance = map_get(2, key)
  let fromBalance = map_get(1, owner)
  abort_if Not((allowance Gte amount))
  abort_if Not((fromBalance Gte amount))
  map[2][key] = (allowance Sub amount) @ Some("true")
  map[1][owner] = (fromBalance Sub amount) @ Some("true")
  map[1][to] = (map_get(1, to) Add amount) @ Some("true")
  return 1
}

function balanceOf(address)(address owner) {
  return map_get(1, owner)
}

function allowanceOf(address,address)(address owner, address spender) {
  let key = keccak256(owner, spender)
  return map_get(2, key)
}
